) AS (
  VALUES 
    (382::BIGINT, 'Las clases no son muy largas. Explica de manera resumida la materia, dándole énfasis a lo que considera más importante. Se dedica a resolver ejercicios la mayoría del tiempo en ellas, lo cual resulta muy útil. Califica bastante pronto y cualquier inconveniente está dispuesto a solucionarlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'bab6eb24fb04bef200823391fa39f3b15a8ca688ce055b61861e6c6dce11f64f'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Es buena nota en general. Si piensan que es difícil, esperense a que conozca al resto de profes de la escuela de electro'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-30T00:00:00+00:00'::TIMESTAMPTZ, '790ef030ccb1a6e36ed25f3a4a7a8cfc0568c80ddac57b3925b1d98a0fe5e7b5'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'vago , no califica nada (solo los asistentes),'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-27T00:00:00+00:00'::TIMESTAMPTZ, '5bb2f375a673b6aa4290c67680fd20f7f4f5da0ccc04359690ad5fa344f6aa07'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Meter con este mae es una trampa! Él es un vago de primera, no califica nada (todo para los asistentes), y cree que es un excelente profesor por pasar con 57.5, pero se lava las manos cuando hay dudas acerca de la calificación. Explica lo normal, pero hace el curso más complicado de lo normal...'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-07T00:00:00+00:00'::TIMESTAMPTZ, '632123538387ee1c8e8d354d6f505788cf0c863ac30a67dbcac07b6c1a451648'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Explica muy bien, en ocasiones se traba, pero por lo general se le entiende muy bien. Si pide ayuda él intenta explicarle, no le gusta la bulla. Califica un poco duro pero al final del semestre ayuda, además sube videos de las clases'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'af1d9c4183f27fa6a900acc27397576ba71c582fab5d20445612d7982d890c70'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Ecplica muy bien pero es demasiado vago. Los asistentes califican a matar, tanto quices como exámenes, lo que dificulta más el curso de lo que es. Lo recomiendo si repite el curso (si no lo había llevado con él).'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c91cbfe95c88afd91d60745345c6312b089e4d094178264c1daf2e76dd407943'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Un curso que sin duda es para estudiar del libro, no puedes depender del profesor para pasarlo, pero el profe es muy buena persona y explica relativamente bien.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'b2ba415be9952626d67d0b935b373d91b1fef6b53a4420c203f7dd5f95078099'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'buena profe'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'edc3c39954a54ac0d77aa5ce5f51e844ed8d8d082bd6747b6885125383b5cc4d'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3192fdd1455d288dab6aca56f4e69f449c790868fcbaaab5296dbf3d68f984e9'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Es buena persona, no le gusta el ruido en la clase y es comprensible porque hay gente que es muy escandalosa, califica bien lo que amerita puntos, explica claro aunque a veces se muestra inseguro. En general es una buena opción'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3d5738ab9ca08aef17153e1d2908a2af7a2e265cfba43e97ed84249ace60322a'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Excelente persona.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f512c3731d68a8d0f2d656e8b300b9437ebfd86c204aa03b920e434a9c22298b'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'De los dos-tres que siempre ponen para CC, es la mejor opción.El tiempo no se aprovecha muy bien en clase, se hace uno a dos ejercicios. Las clases son un complemento al estudio individual que tiene que hacer para el curso. Calificando es muy comprensivo y al final ayuda motones a los que lo ocupen.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'c62198c4d81785548c969dd001c4c01c96b8014c0efe773d5a969c3fb3fabfc2'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'CC es un curso muy difícil y no alcanza con las clases para cubrir todo lo que se evalúa en el examen, el profe es regular y yo personalmente recomiendo estudiar bastante del Sadiku (uno de los libros recomendados para el curso).'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '4a4555e24bd93003633b66c7128cfdebb0b92fe9dbd1d0678dae69042d6f7794'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Normalmente para CC es la mejor opcion. Su leccion se basa en dejar un par de ejercicios en la pizarra, el se va de la clase o atiende unas dudas y luego los resuelve en la pizarra y los explica. En consulta ayuda y los quices pasables. Si le pone pasa, ese curso es ya duro por si solo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, '523e6c7a1f8ed6c8960db7830ecbbf5a0630d289a050b7c85e4de3024d23bd76'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'En realidad no explica nada, llega y pone un ejemplo de tema nuevo y les dice a los estudiantes que intenten hacer el problema y ahi se va toda la clase. El metodo evaluativo del curso en general es duro, virtualmente binario.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'fbee284bf1911e8f7e58f7d7e1b5d910d2beb5cc5d256af2fa15e966c23849e5'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'No es el mejor profe, tiene sus contras como que las clases no son muy provechosas o a veces no explica bien pero en general es una opcion adecuada para llevar cc, con concentracion en clase se puede llegar a entenderle y aprender. Es buena gente, atiende dudas y califica regular.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-01T00:00:00+00:00'::TIMESTAMPTZ, '5717c9344d849602d120d455baf785ae9800608a60947e3acc3ccec3ca0e5db9'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Clases poco provechosas y "mecánicas". Profe regular.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2015-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'fe316eebed97da6481ace069c1591fec0b9b7326ffb365a0f56dc7d19402c16a'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Uno de esos profes que uno despues ni recuerda, que solo es uno mas, cualquiera pasa pero dificilmente aprenda lo necesario y en los siguientes cursos se da cuenta, pone a los estudiantes a hacer practica casi toda la clase sin haber dado un ejemplo previo'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'f68e81b19772e28f97318dda31cc448500943fd1cfb2fe11e471aad4ea9bd6e6'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Hay que estudiar bastante y aprovechar la clase para hacerle consulta sobre los ejercicios que les presentaron dificultades. El el busca la manera de intentar ayudarles a resolver su duda sólo deben esforzarse.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'c58a65304a28f3c954595ee81cd71ec21b55e2d5894848ef98d5e637ffb0f144'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '06330eb5e6aa647e9f20d0311a2408f88d17a183c4fc2653501d7039ba89d84b'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'El profe es malo para explicar. Pone a los estudiantes a resolver ejercicios sin que nadie tenga idea de cómo comenzar si quiera y por esto, las clases no son provechosas, es más, puede que se haga un ejercicio por lección.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '71f2bfa763e0d226a1445acfd89bb3e38b71ab03163a331ef01688f8ad8a7101'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'da teoria y de un solo a puros ejemplos, lo cual esta bien pero para entender hay que ir siempre a lecciones. ademas, es un monumento'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a51aad1550d27d99d36f246a04a5de860d2dfa9686af56ae3aff5ceccfa51f88'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Tiene que estudiar mucho del libro para pasar'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'adb40beac7996b8bb3b09924022fb129b7ac19197f056317189e7ac95c8867c4'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'El mae es malo, no explica nadaaa y cuando uno lo busca lo atiende como por salir del paso, MALO'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'c25c9e6ecbeaf4997451847c0974c80f2b4e38a7783b49ff3e5cbb14debe8eec'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'No califica duro, nada más no explica muy bien, hace un par de ejemplos de cada tema, si usted es bueno para ser autosuficiente (el libro es indispensable) la pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '21cb90884ae144a8b3de1b824d11073f7f2f972f2d74d437d213371ff026ef4e'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Hace ejemplos fáciles para introducir los temas, después sólo pone a los estudiantes a resolver ejercicios. Es un roble.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '47614ee95cf6188e8cbbede78942e4fc44084a520139cd8845cb1da1190ea95b'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '799420f426aba192eda3f7ade5c80bda21ac56493edcdc6f8c69334a66a7fc42'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Pone ejemplos en clases, pero no explica mucha teoría ademas para calificar es muy resultadista'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '1a9e242ee2c20505a508d1d1f8ad326f68a7f4d975ba1520d54beb48663beb1c'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '8316ee28e75b7e30c5a5e7e0029b49ad96d1862bf7b55a5dd725f85be62454da'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a69301350933debd637edea4d6835a6e297a4c5059da191400e11670d5230f7b'::TEXT, ARRAY[1257]::BIGINT[]),
    (382::BIGINT, 'Hace muchos ejemplos pero no explica mucha teoria. Califica medio duro. Es un monumento.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '0f81854f2aec492234cb4b5cf3de24be95d9fdad1d0d61b92baacf26ebf70f8a'::TEXT, ARRAY[1257]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
